#pragma once
#include "map_selection.h"

namespace extractor {
inline void writeExportReadme(const std::filesystem::path& root,const std::string& kind) {
    std::string text;
    const auto server=targetProfile=="all" ? "your selected server format" : targetProfile;
    if (kind=="T3D") {
        text="T3D - MAP ACTORS AND BRUSHES\r\n\r\nUTF-8 Unreal text, one folder per map, one Package.Class.t3d per actor class. Tab indentation, six-decimal floats and signed zero-padded brush vectors follow the reference exports. Local object references use myLevel.; external asset paths are preserved. Includes live actors, level objects, stored properties, nested objects and original brush polygons. External meshes and textures remain package references; use the matching client assets. The selected client System folder supplies property and enum definitions. Missing types or original brush data are reported as skipped exports, never fabricated. These are editable actor exports, not a compiled map or an asset backup. Import into a compatible UnrealEd with the referenced packages available; rebuild geometry and save there.\r\n";
    } else if (kind=="EVENTS") {
        text="MAP EVENTS - REFERENCE CATALOG\r\n\r\nUTF-8 text, one <map>_Events.txt per map containing events. Maps with zero events create no catalog. Classic alternatives are separate. Event IDs are sorted and grouped; each entry contains only the display name, actor name, numeric command and unrounded world Location. Missing EventID/EventCmd/Location fields use Unreal zero defaults. Repeated IDs are retained because multiple actors can respond to one trigger. Name is a display label derived from Tag/Group, with actor name as fallback. Redundant class, array index, raw Tag and Group fields are omitted. Quoted text escapes quotes, backslashes and line breaks.\r\n\r\nThese files are a searchable reference, not a server import format. Scripts can use OnEventTrigger(id, true/false); compatible servers provide //event_trigger id true/false for testing. The client map supplies each effect's behavior and position. Numeric commands are preserved for the selected client's definitions. No live client/server files are modified.\r\n";
    } else if (kind=="PATHNODES") {
        text="PATHNODES - WHAT TO COPY\r\n\r\nCopy the .pn files to the pathnode directory configured by your server. This is the legacy block-centre, eight-link PN layout; verify your server loader supports it. Classic files are alternatives to the normal regions, not additional regions. Missing map neighbours remain closed. Back up existing files and test routes before replacing live data.\r\n";
    } else if (kind=="GEODATA") {
        const char* written=geodataFormat=="l2j" ? "This run wrote L2J/*.l2j only.\r\n" : geodataFormat=="l2off" ? "This run wrote L2OFF/*_conv.dat only.\r\n" : "This run wrote both L2J and L2OFF. Copy only one of those folders.\r\n";
        text=std::string("GEODATA - WHAT TO COPY\r\n\r\n1. Stop your game server before replacing its data.\r\n2. For an L2J-family server, copy the files from L2J into the server's configured geodata folder.\r\n3. L2OFF contains PTS conv.dat files.\r\n4. Classic contains an alternative map set. Use Classic files only with Classic maps; they replace the normal files for those regions.\r\n\r\n")+written+"The cells and the four directions are the same in both formats. Test movement before using the files on a live server.\r\nIf Pathnodes was generated, its .pn files belong in your server's configured pathnode folder. Read Pathnodes/README_PATHNODES.txt first; not every server uses this legacy PN layout.\r\n";
        text+="\r\nTerrain edges use neighbouring maps of the same Normal/Classic variant, including maps you did not select for export. Missing terrain samples use a flat edge extension and are listed as information in the Console. Without neighbouring collision data, movement across that region border stays closed. Meshes whose packages are missing are ignored and identified in Console warnings; their collision is absent from the output. Geometry outside each TerrainInfo's horizontal footprint is excluded; underground and elevated geometry inside the footprint remains eligible.\r\n";
    } else if (kind=="DOORS") {
        text="DOORS - WHAT TO COPY\r\n\r\nServer format: "+std::string(server)+"\r\n\r\n1. Back up your server's existing door definitions.\r\n2. Use doors.xml, or the per-map XML files if you turned off the one-file option.\r\n3. Replace or merge matching door IDs in the file loaded by your server. Keep your server's HP, defenses, ownership and opening scripts. These files provide client geometry, not recovered gameplay rules.\r\n4. Restart or reload door data using your server's normal procedure.\r\n\r\nClient names (optional):\r\n- saticobject-e_ClientDat.txt: import using ClientDat's staticobject text format.\r\n- staticobject-e_FileEdit.txt: import using FileEdit's ID/name text format.\r\nBack up the client DAT before editing it.\r\n\r\nClassic contains alternative definitions for Classic maps. Use one map version at a time; do not merge both sets.\r\nThe exact server filename and directory vary by server version.\r\n";
        if (targetProfile=="l2off" || targetProfile=="all") text+="\r\nL2OFF: merge door_begin records from the .txt files into Script/doordata.txt by editor_id. They are fragments, not a replacement for the full script. Preserve existing script names, references and stats.\r\n";
    } else if (kind=="WATER") {
        text="WATER ZONES - WHAT TO COPY\r\n\r\nServer format: "+std::string(server)+"\r\n\r\n1. Back up your server's existing water-zone definitions.\r\n2. Use water.xml, or the per-map XML files if you turned off the one-file option.\r\n3. Add these water zones to the zone XML loaded by your server. Keep unrelated zones. Do not load the same water zones twice.\r\n4. Restart or reload zone data using your server's normal procedure.\r\n\r\naCis: use the WaterZone loader's zone file.\r\nL2Scripts: keep the matching zones schema and DTD expected by your version.\r\nClassic contains alternative definitions. Use them only with Classic maps.\r\nThe exact zone filename and directory vary by server version.\r\n";
        if (targetProfile=="l2off" || targetProfile=="all") text+="\r\nL2OFF: merge the .txt area fragments into Script/areadata.txt. Keep existing non-water areas. Do not replace the full script with these fragments.\r\n";
    } else text="MAP CHECK\r\n\r\nmap-details.json is a technical inventory of the selected client maps. It is not a file to install on your server.\r\n";
    if (targetProfile=="all" && kind!="GEODATA" && kind!="EVENTS" && kind!="T3D") text+="\r\nChoose only the folder matching your server. Do not install every server format.\r\n";
    output::save(root/("README_"+kind+".txt"),text);
}
}
